  "evidence": [
   {
    "quote": "in (^\\d+).*\\1, the ^ constraint should be applied at the start of the string, but not when matching \\1",
    "source": "PostgreSQL 14 release notes: Migration to Version 14",
    "release_of_change": "14"
   }
  ]
 }
]
